using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
string WebSearch(string query)
{
    // In production, replace with a real search API (e.g., Bing Search).
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
    return $"Search results for '{query}':\n" +
           $"1. {query} is a widely discussed topic with recent developments in 2026.\n" +
           $"2. Experts highlight key advances and ongoing challenges related to {query}.\n" +
           $"3. A recent survey found growing public interest in {query} across multiple sectors.";
}

[Description("Save a research note for later use in the summary. Use this to record key findings.")]
string TakeNote(string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

// --- Agent Setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

// --- Agent Loop ---

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research agent. Your job is to research the given topic thoroughly by:
        1. Performing multiple web searches with different queries to gather diverse information.
        2. Taking notes on key findings as you go.
        3. After gathering enough information, retrieve your notes and produce a well-structured summary.

        Always use the tools available to you. Search at least 2-3 times with varied queries,
        take notes on important findings, then provide a final summary to the user.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

